"use client";
import { useEffect, useState } from "react";
import { Calendar, ArrowLeft } from "lucide-react";
import Link from "next/link";

const BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export default function PostDetailPage({ params }) {
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (params?.id) {
      loadPost(params.id);
    }
  }, [params]);

  const loadPost = async (id) => {
    setLoading(true);
    try {
      const res = await fetch(`${BASE_URL}/api/posts/${id}`);
      if (!res.ok) throw new Error("Failed to fetch post");

      const data = await res.json();
      setPost(data);
      document.title = `${data.title} | CCUG`;
    } catch (err) {
      console.error(err);
      setError("Failed to load post.");
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen ccug-bg text-white flex items-center justify-center">
        <div className="animate-spin h-12 w-12 border-b-2 border-ccug-purple rounded-full"></div>
      </div>
    );
  }

  if (error || !post) {
    return (
      <div className="min-h-screen ccug-bg text-white">
        <div className="max-w-5xl mx-auto px-4 py-12">
          <div className="bg-red-500/20 border border-red-500/50 rounded-lg p-6 text-center">
            <p className="text-red-300 text-lg mb-4">{error || "Post not found"}</p>
            <Link 
              href="/posts"
              className="text-ccug-purple hover:text-ccug-purple/80 underline"
            >
              Back to Posts
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen ccug-bg text-white">
      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {/* Back Button */}
        <Link 
          href="/posts"
          className="inline-flex items-center gap-2 text-ccug-gray hover:text-white transition mb-6"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Posts
        </Link>

        {/* Breadcrumb */}
        <div className="mb-6">
          <p className="text-ccug-gray text-sm">
            <Link href="/" className="hover:text-white transition">
              Home
            </Link>
            <span className="mx-2">»</span>
            <Link href="/posts" className="hover:text-white transition">
              Posts
            </Link>
            <span className="mx-2">»</span>
            <span className="text-white">{post.title}</span>
          </p>
        </div>

        {/* Title */}
        <h1 className="text-3xl sm:text-4xl font-bold mb-4 text-green-400">
          {post.title}
        </h1>

        {/* Metadata */}
        <div className="flex flex-wrap items-center gap-3 text-sm sm:text-base text-ccug-gray mb-8">
          <span className="flex items-center gap-2">
            <Calendar className="w-4 h-4" /> {formatDate(post.date)}
          </span>
          <span>•</span>
          <span className="px-3 py-1 bg-ccug-purple/20 rounded-full text-ccug-purple border border-ccug-purple/50">
            {post.category}
          </span>
          <span>•</span>
          <span className="text-white font-medium">by {post.author}</span>
        </div>

        <div className="border-b border-ccug-purple mb-8"></div>

        {/* Description/Content */}
        <article className="prose prose-invert prose-lg max-w-none">
          <div className="text-ccug-gray leading-relaxed whitespace-pre-wrap">
            {post.description}
          </div>
        </article>

        {/* External URL Link */}
        {post.url && post.url !== "test" && (
          <div className="mt-8 p-4 bg-ccug-purple/10 border border-ccug-purple/30 rounded-lg">
            <p className="text-sm text-ccug-gray mb-2">Full writeup available at:</p>
            <a
              href={post.url}
              target="_blank"
              rel="noopener noreferrer"
              className="text-ccug-purple hover:text-ccug-purple/80 underline break-all"
            >
              {post.url}
            </a>
          </div>
        )}

        <div className="border-b border-ccug-gray/30 mt-12"></div>

        {/* Footer Navigation */}
        <div className="mt-8">
          <Link
            href="/posts"
            className="inline-flex items-center gap-2 text-ccug-purple hover:text-ccug-purple/80 transition"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to all posts
          </Link>
        </div>
      </main>
    </div>
  );
}